import React, { useContext, useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import { Link as RouterLink, useNavigate, useLocation } from 'react-router-dom';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Box,
  Avatar,
  IconButton,
  Menu,
  MenuItem,
  Divider,
  Tooltip,
  useScrollTrigger,
  alpha,
  useTheme,
  Container,
} from '@mui/material';
import {
  Menu as MenuIcon,
  Dashboard as DashboardIcon,
  Person as PersonIcon,
  ExitToApp as LogoutIcon,
  AdminPanelSettings as AdminPanelSettingsIcon,
  Article as ArticleIcon,
  Home as HomeIcon,
  ExpandMore as ExpandMoreIcon,
  Brightness4 as DarkModeIcon,
  Brightness7 as LightModeIcon,
} from '@mui/icons-material';
import { useTheme as useAppTheme } from '../../context/ThemeContext';
import { useDispatch, useSelector } from 'react-redux';
import { logout as logoutAction, selectCurrentUser } from '../../features/auth/authSlice';
import AlertContext from '../../context/alert/alertContext';

function HideOnScroll(props) {
  const { children } = props;
  const location = useLocation();
  const isDashboard = location.pathname === '/dashboard';
  
  // Don't hide on scroll for dashboard
  if (isDashboard) {
    return (
      <AppBar 
        position="fixed"
        sx={{
          background: 'rgba(255, 255, 255, 0.95) !important',
          backdropFilter: 'blur(10px)',
          WebkitBackdropFilter: 'blur(10px)',
          borderBottom: '1px solid rgba(0, 0, 0, 0.1) !important',
          boxShadow: '0 2px 10px rgba(0, 0, 0, 0.05) !important',
        }}
      >
        {children}
      </AppBar>
    );
  }

  const trigger = useScrollTrigger({
    disableHysteresis: true,
    threshold: 0
  });

  return (
    <AppBar 
      position="fixed"
      sx={{
        transition: 'all 0.3s ease-in-out',
        transform: trigger ? 'translateY(-100%)' : 'translateY(0)',
        boxShadow: trigger ? 'none' : '0 4px 20px 0 rgba(0, 0, 0, 0.1)',
      }}
    >
      {children}
    </AppBar>
  );
}

const Navbar = (props) => {
  const { onFilterChange = () => {} } = props;
  const dispatch = useDispatch();
  const user = useSelector(selectCurrentUser);
  const isAuthenticated = !!user;
  const alertContext = useContext(AlertContext);
  const { setAlert } = alertContext;
  const navigate = useNavigate();
  const [anchorEl, setAnchorEl] = useState(null);
  const [newsAnchorEl, setNewsAnchorEl] = useState(null);
  const [scrolled, setScrolled] = useState(false);
  const theme = useTheme();
  const { mode, toggleTheme } = useAppTheme();
  const isAdmin = user && user.role === 'admin';

  // Handle scroll effect
  useEffect(() => {
    const handleScroll = () => {
      const isScrolled = window.scrollY > 10;
      if (isScrolled !== scrolled) {
        setScrolled(isScrolled);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [scrolled]);
  
  // Suppress unused variable warnings
  const location = useLocation();

  const handleMenu = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleNewsMenuOpen = (event) => {
    setNewsAnchorEl(event.currentTarget);
  };

  const handleNewsMenuClose = () => {
    setNewsAnchorEl(null);
  };

  const [country, setCountry] = useState('us');
  const [fromDate, setFromDate] = useState(null);
  const [toDate, setToDate] = useState(null);
  const [showFilters, setShowFilters] = useState(false);

  const handleNewsCategoryClick = (category) => {
    const params = new URLSearchParams();
    params.set('category', category.toLowerCase());
    if (country) params.set('country', country);
    if (fromDate) params.set('fromDate', fromDate.toISOString());
    if (toDate) params.set('toDate', toDate.toISOString());
    
    navigate(`/dashboard?${params.toString()}`);
    handleNewsMenuClose();
  };

  const handleCountryChange = (event) => {
    const newCountry = event.target.value;
    setCountry(newCountry);
    
    // Update URL with new country
    const params = new URLSearchParams(window.location.search);
    params.set('country', newCountry);
    window.history.pushState({}, '', `${window.location.pathname}?${params.toString()}`);
    
    // Trigger filter change in parent
    onFilterChange({ country: newCountry });
  };

  const handleDateChange = (date, type) => {
    if (type === 'from') {
      setFromDate(date);
      // Update URL with new date
      const params = new URLSearchParams(window.location.search);
      if (date) {
        params.set('fromDate', date.toISOString());
      } else {
        params.delete('fromDate');
      }
      window.history.pushState({}, '', `${window.location.pathname}?${params.toString()}`);
      
      // Trigger filter change in parent
      onFilterChange({ fromDate: date });
    } else {
      setToDate(date);
      // Update URL with new date
      const params = new URLSearchParams(window.location.search);
      if (date) {
        params.set('toDate', date.toISOString());
      } else {
        params.delete('toDate');
      }
      window.history.pushState({}, '', `${window.location.pathname}?${params.toString()}`);
      
      // Trigger filter change in parent
      onFilterChange({ toDate: date });
    }
  };

  const onLogout = () => {
    handleClose();
    dispatch(logoutAction());
    setAlert('Logged out successfully', 'success');
    navigate('/login');
  };

  const authLinks = (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
      <Button
        component={RouterLink}
        to="/dashboard"
        color="inherit"
        startIcon={<DashboardIcon />}
        sx={{
          display: { xs: 'none', md: 'flex' },
          color: theme.palette.common.white,
          '&:hover': {
            backgroundColor: alpha(theme.palette.common.white, 0.1),
          },
          mr: 1,
        }}
      >
        Dashboard
      </Button>
      
      <Tooltip title="Account settings">
        <IconButton
          onClick={handleMenu}
          className="btn-glass"
          sx={{
            p: 1,
            ml: 2,
            '&.btn-glass': {
              backgroundColor: 'rgba(255, 255, 255, 0.3) !important',
              '&:hover': {
                backgroundColor: 'rgba(255, 255, 255, 0.4) !important',
              },
            },
          }}
          aria-controls="menu-appbar"
          aria-haspopup="true"
        >
          <Avatar
            alt={user?.username || 'User'}
            src="/static/images/avatar/1.jpg"
            sx={{ 
              width: 32, 
              height: 32,
              bgcolor: theme.palette.secondary.main,
            }}
          >
            {user?.username?.charAt(0).toUpperCase()}
          </Avatar>
        </IconButton>
      </Tooltip>
      
      <Menu
        id="menu-appbar"
        className="glass-effect"
        anchorEl={anchorEl}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        keepMounted
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
        open={Boolean(anchorEl)}
        onClose={handleClose}
        PaperProps={{
          elevation: 0,
          sx: {
            overflow: 'visible',
            background: 'rgba(255, 255, 255, 0.9) !important',
            backdropFilter: 'blur(10px)',
            WebkitBackdropFilter: 'blur(10px)',
            border: '1px solid rgba(255, 255, 255, 0.3)',
            boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.15)',
            borderRadius: '12px',
            mt: 1.5,
            '& .MuiAvatar-root': {
              width: 32,
              height: 32,
              ml: -0.5,
              mr: 1,
            },
            '&:before': {
              content: '""',
              display: 'block',
              position: 'absolute',
              top: 0,
              right: 14,
              width: 10,
              height: 10,
              background: 'rgba(255, 255, 255, 0.9)',
              backdropFilter: 'blur(10px)',
              WebkitBackdropFilter: 'blur(10px)',
              borderTop: '1px solid rgba(255, 255, 255, 0.3)',
              borderLeft: '1px solid rgba(255, 255, 255, 0.3)',
              transform: 'translateY(-50%) rotate(45deg)',
              zIndex: 0,
            },
          },
        }}
      >
        <Box sx={{ px: 2, py: 1.5, borderBottom: `1px solid ${theme.palette.divider}` }}>
          <Typography variant="subtitle2" fontWeight="600">
            {user?.name || 'User'}
          </Typography>
          <Typography variant="caption" color="text.secondary">
            {user?.email || ''}
          </Typography>
        </Box>
        
        <MenuItem 
          component={RouterLink} 
          to="/profile" 
          onClick={handleClose}
          sx={{ py: 1.5 }}
        >
          <PersonIcon sx={{ mr: 1.5, color: 'text.secondary' }} /> 
          Profile
        </MenuItem>
        
        {user?.role === 'admin' && (
          <MenuItem 
            component={RouterLink} 
            to="/admin" 
            onClick={handleClose}
            sx={{ py: 1.5 }}
          >
            <AdminPanelSettingsIcon sx={{ mr: 1.5, color: 'text.secondary' }} /> 
            Admin Dashboard
          </MenuItem>
        )}
        
        <Divider sx={{ my: 1 }} />
        
        <MenuItem 
          onClick={onLogout}
          sx={{ py: 1.5, color: theme.palette.error.main }}
        >
          <LogoutIcon sx={{ mr: 1.5 }} /> 
          Logout
        </MenuItem>
      </Menu>
    </Box>
  );

  const guestLinks = (
    <Tooltip title="Login">
      <IconButton
        component={RouterLink}
        to="/login"
        className="btn-glass"
        sx={{
          p: 1,
          '&.btn-glass': {
            backgroundColor: 'rgba(255, 255, 255, 0.3) !important',
            '&:hover': {
              backgroundColor: 'rgba(255, 255, 255, 0.4) !important',
            },
          },
        }}
        aria-label="login"
      >
        <PersonIcon sx={{ color: theme.palette.common.white }} />
      </IconButton>
    </Tooltip>
  );


  return (
    <HideOnScroll>
      <AppBar
        position="fixed"
        color="transparent"
        elevation={0}
        className="nav-glass"
        sx={{
          '&.nav-glass': {
            background: 'rgba(255, 255, 255, 0.95) !important',
            backdropFilter: 'blur(10px)',
            WebkitBackdropFilter: 'blur(10px)',
            border: '1px solid rgba(0, 0, 0, 0.1) !important',
            boxShadow: '0 2px 10px rgba(0, 0, 0, 0.05) !important',
            color: theme.palette.text.primary,
            '& .MuiButton-root': {
              color: theme.palette.text.primary,
              '&:hover': {
                color: theme.palette.primary.main,
                backgroundColor: 'rgba(0, 0, 0, 0.03)',
              },
            },
            '& .MuiIconButton-root': {
              color: theme.palette.text.primary,
              '&:hover': {
                backgroundColor: 'rgba(0, 0, 0, 0.05)',
              },
            },
          },
        }}
      >
        <Container maxWidth="xl">
          <Toolbar
            sx={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              px: { xs: 2, sm: 4 },
              py: 1,
              maxWidth: '1600px',
              width: '100%',
              margin: '0 auto',
            }}
          >
            {/* Logo / Brand */}
            <Button
              component={RouterLink}
              to="/dashboard"
              className="btn-glass"
              sx={{
                mr: 2,
                display: 'flex',
                alignItems: 'center',
                textTransform: 'none',
                fontWeight: 700,
                fontSize: '1.2rem',
                '&.btn-glass': {
                  backgroundColor: 'rgba(255, 255, 255, 0.3) !important',
                  '&:hover': {
                    backgroundColor: 'rgba(255, 255, 255, 0.4) !important',
                  },
                },
              }}
            >
              <Box sx={{ flexGrow: 1, display: 'flex', alignItems: 'center' }}>
                <Typography
                  variant="h6"
                  component={RouterLink}
                  to="/"
                  sx={{
                    fontWeight: 800,
                    textDecoration: 'none',
                    display: 'flex',
                    alignItems: 'center',
                    background: (theme) => theme.palette.mode === 'dark' 
                      ? 'linear-gradient(45deg, #64b5f6 0%, #1e88e5 100%)' 
                      : 'linear-gradient(45deg, #1976d2 0%, #0d47a1 100%)',
                    WebkitBackgroundClip: 'text',
                    WebkitTextFillColor: 'transparent',
                    backgroundClip: 'text',
                    textFillColor: 'transparent',
                    '&:hover': {
                      opacity: 0.9,
                    },
                    transition: 'all 0.3s ease',
                  }}
                >
                  PulsePoint
                </Typography>
                
                <Box sx={{ display: 'flex', ml: 2 }}>
                  <Tooltip title={mode === 'light' ? 'Dark mode' : 'Light mode'}>
                    <IconButton 
                      onClick={toggleTheme} 
                      color="inherit"
                      sx={{ ml: 1 }}
                      aria-label="toggle theme"
                    >
                      {mode === 'light' ? <DarkModeIcon /> : <LightModeIcon />}
                    </IconButton>
                  </Tooltip>
                </Box>
              </Box>
            </Button>

            {/* Navigation Links */}
            <Box sx={{ flexGrow: 1, display: { xs: 'none', md: 'flex' }, ml: 4 }}>
              <Button
                component={RouterLink}
                to="/home"
                color={scrolled ? 'primary' : 'inherit'}
                startIcon={<HomeIcon />}
                sx={{
                  display: { xs: 'none', md: 'flex' },
                  fontWeight: 500,
                  '&:hover': {
                    backgroundColor: alpha(theme.palette.common.white, 0.1),
                  },
                }}
              >
                Home
              </Button>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <Button
                  onClick={handleNewsMenuOpen}
                  color="inherit"
                  startIcon={<ArticleIcon />}
                  endIcon={<ExpandMoreIcon />}
                  sx={{
                    display: { xs: 'none', md: 'flex' },
                    fontWeight: 500,
                    '&:hover': {
                      backgroundColor: alpha(theme.palette.common.white, 0.1),
                    },
                  }}
                >
                  News
                </Button>
                <Menu
                  anchorEl={newsAnchorEl}
                  open={Boolean(newsAnchorEl)}
                  onClose={handleNewsMenuClose}
                  PaperProps={{
                    elevation: 3,
                    sx: {
                      mt: 2,
                      minWidth: 200,
                      borderRadius: 2,
                      overflow: 'visible',
                      '& .MuiMenu-list': {
                        p: 1,
                      },
                    },
                  }}
                >
                  <MenuItem onClick={() => handleNewsCategoryClick('top-categories')}>
                    <ArticleIcon sx={{ mr: 1.5, fontSize: 20, color: 'primary.main' }} />
                    <Box>
                      <Typography variant="body1" fontWeight="500">Top Categories</Typography>
                      <Typography variant="caption" color="text.secondary">Browse by popular categories</Typography>
                    </Box>
                  </MenuItem>
                  <Divider sx={{ my: 1 }} />
                  <MenuItem onClick={() => handleNewsCategoryClick('most-viewed')}>
                    <ArticleIcon sx={{ mr: 1.5, fontSize: 20, color: 'secondary.main' }} />
                    <Box>
                      <Typography variant="body1" fontWeight="500">Most Viewed</Typography>
                      <Typography variant="caption" color="text.secondary">See what's trending now</Typography>
                    </Box>
                  </MenuItem>
                  <Divider sx={{ my: 1 }} />
                  <MenuItem onClick={() => handleNewsCategoryClick('trending')}>
                    <ArticleIcon sx={{ mr: 1.5, fontSize: 20, color: 'success.main' }} />
                    <Box>
                      <Typography variant="body1" fontWeight="500">Trending News</Typography>
                      <Typography variant="caption" color="text.secondary">Hot topics right now</Typography>
                    </Box>
                  </MenuItem>
                  <Divider sx={{ my: 1 }} />
                  <MenuItem onClick={() => handleNewsCategoryClick('breaking')}>
                    <ArticleIcon sx={{ mr: 1.5, fontSize: 20, color: 'error.main' }} />
                    <Box>
                      <Typography variant="body1" fontWeight="500">Breaking News</Typography>
                      <Typography variant="caption" color="text.secondary">Latest updates</Typography>
                    </Box>
                  </MenuItem>
                  <Divider sx={{ my: 1 }} />
                  <MenuItem 
                    onClick={() => {
                      navigate('/news');
                      handleNewsMenuClose();
                    }}
                    sx={{
                      backgroundColor: 'primary.light',
                      '&:hover': {
                        backgroundColor: 'primary.main',
                        '& .MuiTypography-root': {
                          color: 'white',
                        },
                        '& .MuiSvgIcon-root': {
                          color: 'white',
                        }
                      },
                      mt: 1,
                      borderRadius: 1,
                    }}
                  >
                    <ArticleIcon sx={{ mr: 1.5, fontSize: 20 }} />
                    <Typography variant="body1" fontWeight="600">Search All News</Typography>
                  </MenuItem>
                </Menu>
              </Box>
            </Box>

            {/* Mobile Menu */}
            <Box sx={{ display: { xs: 'flex', md: 'none' }, flexGrow: 1, justifyContent: 'flex-end' }}>
              <IconButton
                size="large"
                aria-label="show more"
                aria-haspopup="true"
                color="inherit"
              >
                <MenuIcon />
              </IconButton>
            </Box>

            {/* Auth Links */}
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              {isAuthenticated ? authLinks : guestLinks}
            </Box>
          </Toolbar>
        </Container>
      </AppBar>
    </HideOnScroll>
  );
};

Navbar.propTypes = {
  onFilterChange: PropTypes.func
};

export default Navbar;
